1	import { access, cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
2	import { spawn } from 'node:child_process';
3	import { basename, dirname, join, relative, resolve } from 'pathe';
4	import { canonicalize, sha256 } from '../../../core/src/receipts/canonicalize.ts';
5	import {
6		ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS,
7		ANGULAR_TINY_TRANSLATOR_FIXTURE,
8		ANGULAR_TINY_TRANSLATOR_SOURCE,
9		parseWitnessAngularTinyTranslatorReceipt,
10		renderWitnessAngularTinyTranslatorReceipt,
11		WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
12		WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE,
13		WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE,
14		WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES,
15		WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE,
16		WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
17		WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA,
18		WITNESS_ANGULAR_TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
19		WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
20		WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES,
21		witnessAngularTinyTranslatorBehaviorDigest,
22		witnessAngularTinyTranslatorDigest,
23		witnessAngularTinyTranslatorRawDigest,
24		type WitnessAngularTinyTranslatorMutation,
25		type WitnessAngularTinyTranslatorReceipt,
26		type WitnessAngularTinyTranslatorRun,
27	} from '../../../core/src/receipts/witness-angular-tiny-translator.ts';
28	import {
29		WITNESS_DOWNLOAD_CAPTURE_RULE,
30		WITNESS_FILE_INPUT_LOAD_RULE,
31	} from '../../../core/src/receipts/witness-real-app.ts';
32	import {
33		executeAngularTinyTranslatorWitnessRun,
34		TINY_TRANSLATOR_MUTATION_SEAM,
35		WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS,
36		WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS,
37	} from './real-app-run.ts';
38	import { verifyLinkedWitnessProvenance } from './provenance.ts';
39	
40	const root = resolve(import.meta.dirname, '../../../..');
41	const fixtureEvidence = join(root, 'evidence/runs/angular-tiny-translator-v0-12-0');
42	const witnessEvidence = join(root, 'evidence/runs/witness-angular-tiny-translator-v0-12-0');
43	const stageRoot = join(root, '.versionless/stage/witness-angular-tiny-translator-v0-12-0');
44	/**
45	 * The migrated lane's build tree, and the output root the u19f record pins as
46	 * canonical. The tree is a working directory rather than committed bytes, so
47	 * this proof cannot assume it survived: {@link migratedLaneRoot} regenerates it
48	 * from the committed flow when it is absent and, either way, refuses to serve
49	 * it until it matches the inventory the record published.
50	 *
51	 * The root is `dist-11`, not `dist-7`. u17d's `dist-7` is a green, deterministic
52	 * build whose artifact throws before Angular bootstraps — the thing u19d found
53	 * by opening it in a browser — and u19f supersedes it with the tree that mounts.
54	 */
55	const migratedStage = join(root, '.versionless/stage/angular-tiny-translator-v0-12-0-u17b');
56	const sourceOutputs = {
57		baseline: join(
58			root,
59			'.versionless/cache/angular-tiny-translator-v0-12-0-baseline/app/dist/rebuild-1',
60		),
61		migrated: join(migratedStage, 'dist-11'),
62	} as const;
63	/** The build the u19f record pins for the canonical output root. */
64	const MIGRATED_BUILD_COMMAND = 'npx ng build --configuration production' as const;
65	const laneFileCounts = { baseline: 524, migrated: 524 } as const;
66	
67	type InventoryEntry = { path: string; sha256: string; bytes: number };
68	
69	async function exists(path: string): Promise<boolean> {
70		return access(path).then(
71			() => true,
72			() => false,
73		);
74	}
75	
76	async function files(directory: string): Promise<string[]> {
77		const output: string[] = [];
78		for (const entry of await readdir(directory, { withFileTypes: true })) {
79			const path = join(directory, entry.name);
80			if (entry.isDirectory()) output.push(...(await files(path)));
81			else if (entry.isFile()) output.push(path);
82		}
83		return output.sort();
84	}
85	
86	/** Every file of an emitted artifact, addressed exactly as the u19f record does. */
87	async function inventoryOf(rootDirectory: string): Promise<InventoryEntry[]> {
88		const entries: InventoryEntry[] = [];
89		for (const file of await files(rootDirectory)) {
90			const bytes = await readFile(file);
91			entries.push({
92				path: relative(rootDirectory, file),
93				sha256: sha256(bytes),
94				bytes: bytes.length,
95			});
96		}
97		return entries;
98	}
99	
100	/** The pinned migrated build record, re-read rather than restated. */
101	async function migratedLaneRecord(): Promise<{
102		inventory: InventoryEntry[];
103		inventorySha256: string;
104	}> {
105		const pinned = ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.find(
106			(receipt) => receipt.lane === 'migrated',
107		);
108		if (pinned === undefined) throw new Error('TinyTranslator migrated lane binding is absent');
109		const bytes = await readFile(join(root, pinned.path));
110		if (sha256(bytes) !== pinned.sha256)
111			throw new Error(`TinyTranslator bound build receipt bytes drifted: ${pinned.path}`);
112		const record = JSON.parse(bytes.toString('utf8')) as {
113			inventory?: InventoryEntry[];
114			determinism?: { inventorySha256?: string };
115		};
116		const inventory = record.inventory;
117		const inventorySha256 = record.determinism?.inventorySha256;
118		if (!Array.isArray(inventory) || typeof inventorySha256 !== 'string')
119			throw new Error('TinyTranslator migrated lane record publishes no inventory to verify');
120		return { inventory, inventorySha256 };
121	}
122	
123	/**
124	 * The digest the u19f record computed over its own inventory: the pretty-printed
125	 * JSON array with a trailing newline, exactly as the recording flow wrote it.
126	 * Recomputing it here rather than accepting the record's own number is what
127	 * makes the comparison a check instead of a restatement.
128	 */
129	function inventoryDigest(inventory: readonly InventoryEntry[]): string {
130		return sha256(`${JSON.stringify(inventory, null, 2)}\n`);
131	}
132	
133	async function run(command: string, args: readonly string[], cwd: string): Promise<void> {
134		await new Promise<void>((settle, fail) => {
135			const child = spawn(command, [...args], {
136				cwd,
137				stdio: 'ignore',
138				env: {
139					...process.env,
140					VERSIONLESS_NETWORK_MODE: 'offline',
141					NPM_CONFIG_OFFLINE: 'true',
142				},
143			});
144			child.on('error', fail);
145			child.on('close', (code) =>
146				code === 0
147					? settle()
148					: fail(new Error(`TinyTranslator regeneration command failed: ${command} (${code})`)),
149			);
150		});
151	}
152	
153	/**
154	 * The migrated lane's canonical output root, regenerated when it is missing and
155	 * verified either way.
156	 *
157	 * The regeneration is the same offline production build the u19f record pins,
158	 * run over the same staged application tree that record itemises; nothing is
159	 * re-migrated here, because the migration is already applied in that tree. The
160	 * verification is what the proof actually rests on: the emitted inventory has
161	 * to reproduce the record's own 524-file inventory, file for file and digest
162	 * for digest, and its digest has to reproduce the record's `inventorySha256`.
163	 * A tree that regenerated differently is refused rather than served.
164	 */
165	async function migratedLaneRoot(): Promise<string> {
166		const record = await migratedLaneRecord();
167		if (!(await exists(sourceOutputs.migrated))) {
168			const application = join(migratedStage, 'app');
169			if (!(await exists(application)))
170				throw new Error(
171					'TinyTranslator migrated lane cannot be regenerated: the staged application tree is absent',
172				);
173			const [command, ...args] = MIGRATED_BUILD_COMMAND.split(' ');
174			await run(command!, [...args, '--output-path', sourceOutputs.migrated], application);
175		}
176		const emitted = await inventoryOf(sourceOutputs.migrated);
177		const emittedDigest = inventoryDigest(emitted);
178		if (canonicalize(emitted) !== canonicalize(record.inventory))
179			throw new Error(
180				`TinyTranslator migrated lane inventory differs from the pinned record: ${emittedDigest} against ${record.inventorySha256}`,
181			);
182		if (emittedDigest !== record.inventorySha256)
183			throw new Error(
184				`TinyTranslator migrated lane inventory digest differs: ${emittedDigest} against ${record.inventorySha256}`,
185			);
186		return sourceOutputs.migrated;
187	}
188	
189	async function stageInputs(): Promise<Record<'baseline' | 'migrated', string>> {
190		const migrated = await migratedLaneRoot();
191		const lanes = join(stageRoot, 'lanes');
192		await rm(lanes, { recursive: true, force: true });
193		const staged = { baseline: join(lanes, 'baseline'), migrated: join(lanes, 'migrated') };
194		const outputs = { baseline: sourceOutputs.baseline, migrated } as const;
195		for (const lane of ['baseline', 'migrated'] as const) {
196			if (!(await exists(outputs[lane])))
197				throw new Error(`TinyTranslator ${lane} production output is absent`);
198			await mkdir(dirname(staged[lane]), { recursive: true });
199			await cp(outputs[lane], staged[lane], { recursive: true, force: false });
200			const stagedFiles = await files(staged[lane]);
201			if (stagedFiles.length !== laneFileCounts[lane])
202				throw new Error(
203					`TinyTranslator ${lane} lane file count differs: ${stagedFiles.length} against ${laneFileCounts[lane]}`,
204				);
205		}
206		return staged;
207	}
208	
209	async function executeRuns(
210		lanes: Record<'baseline' | 'migrated', string>,
211	): Promise<WitnessAngularTinyTranslatorRun[]> {
212		const runs: WitnessAngularTinyTranslatorRun[] = [];
213		for (const lane of ['baseline', 'migrated'] as const)
214			for (const pass of [1, 2] as const) {
215				const raw = await executeAngularTinyTranslatorWitnessRun({
216					lane,
217					pass,
218					laneRoot: lanes[lane],
219					receiptRoot: join(stageRoot, 'receipts'),
220				});
221				const candidate = raw as WitnessAngularTinyTranslatorRun;
222				if (candidate.semanticDigest !== witnessAngularTinyTranslatorRawDigest(candidate))
223					throw new Error(`TinyTranslator ${lane} pass ${pass} raw digest differs`);
224				runs.push({
225					...candidate,
226					behaviorDigest: witnessAngularTinyTranslatorBehaviorDigest(candidate),
227				});
228			}
229		if (new Set(runs.map((entry) => entry.behaviorDigest)).size !== 1)
230			throw new Error('TinyTranslator baseline/migrated behavior parity differs');
231		return runs;
232	}
233	
234	/**
235	 * Byte mutation on the migrated build.
236	 *
237	 * The seam is the visible label of the control that opens the file picker: a
238	 * string a reader sees, asserted exactly by the journey on the create-project
239	 * route, and the name of the very mechanism this vertical exists to exercise.
240	 * The uniqueness demanded here is the corpus discipline — exactly one served
241	 * module may carry it, exactly once — so overwriting it in place cannot be
242	 * absorbed by a second copy elsewhere in the bundle.
243	 */
244	async function semanticMutation(
245		laneRoot: string,
246		behaviorDigest: string,
247	): Promise<WitnessAngularTinyTranslatorMutation> {
248		const expected = Buffer.from(TINY_TRANSLATOR_MUTATION_SEAM);
249		const candidates: Array<{ path: string; offset: number }> = [];
250		for (const path of await files(laneRoot)) {
251			const bytes = await readFile(path);
252			const offset = bytes.indexOf(expected);
253			if (offset < 0) continue;
254			if (bytes.lastIndexOf(expected) !== offset)
255				throw new Error('TinyTranslator semantic seam is not unique within its file');
256			candidates.push({ path, offset });
257		}
258		const target = candidates[0];
259		if (candidates.length !== 1 || target === undefined || !target.path.endsWith('.js'))
260			throw new Error('TinyTranslator semantic seam is not a single served module');
261		const before = await readFile(target.path);
262		const mutated = Buffer.from(before);
263		Buffer.alloc(expected.length, 'X').copy(mutated, target.offset);
264		const beforeSha256 = sha256(before);
265		const mutatedSha256 = sha256(mutated);
266		let intendedFailure = false;
267		try {
268			await writeFile(target.path, mutated);
269			try {
270				await executeAngularTinyTranslatorWitnessRun({
271					lane: 'migrated',
272					pass: 1,
273					laneRoot,
274					receiptRoot: join(stageRoot, 'mutation-receipt'),
275				});
276			} catch (error) {
277				const message = error instanceof Error ? error.message : String(error);
278				intendedFailure = message.includes(TINY_TRANSLATOR_MUTATION_SEAM);
279			}
280		} finally {
281			await writeFile(target.path, before);
282		}
283		const afterRestoreSha256 = sha256(await readFile(target.path));
284		if (!intendedFailure || afterRestoreSha256 !== beforeSha256)
285			throw new Error('TinyTranslator semantic mutation was not exact red and byte-restored');
286		const restored = (await executeAngularTinyTranslatorWitnessRun({
287			lane: 'migrated',
288			pass: 1,
289			laneRoot,
290			receiptRoot: join(stageRoot, 'restoration-receipt'),
291		})) as WitnessAngularTinyTranslatorRun;
292		const restoredBehaviorDigest = witnessAngularTinyTranslatorBehaviorDigest(restored);
293		if (restoredBehaviorDigest !== behaviorDigest)
294			throw new Error('TinyTranslator restored browser behavior differs');
295		return {
296			failure: 'witness-semantic-assertion',
297			intendedFailure: true,
298			lane: 'migrated',
299			seam: TINY_TRANSLATOR_MUTATION_SEAM,
300			path: relative(laneRoot, target.path),
301			offset: target.offset,
302			beforeSha256,
303			mutatedSha256,
304			afterRestoreSha256,
305			restoredByteIdentically: true,
306			restoredRun: 'pass',
307			restoredBehaviorDigest,
308		};
309	}
310	
311	/**
312	 * The nonclaims this proof publishes. Each one names something a reader could
313	 * otherwise assume from the rest of the receipt and states plainly that it is
314	 * not established here.
315	 */
316	export const WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS: readonly string[] = Object.freeze([
317		'This is one Angular lineage under direct Witness and does not establish generic Angular, Angular CLI 1.5, `.angular-cli.json` workspaces, or `@angular-devkit/build-angular:browser` support.',
318		'The Angular lineage readiness score is unchanged; this vertical is not counted before Judge audit.',
319		'There is no backend and nothing was stubbed or seeded by the harness. The project the journey works on is created by the application itself, from a file this proof hands its own file input, and everything it keeps it keeps in browser local storage.',
320		'The translation file handed to the page is synthetic and authored for this proof. It carries no upstream project’s strings and no third party’s translated content, and it is bound by name, length and digest so a journey cannot quietly load a different one.',
321		'The file the page produced is read back by name, byte length and digest, and its content is asserted rather than published: a produced translation file is the application’s data, not this receipt’s.',
322		'Neither lane ends up with the Material Icons glyphs, and the two lanes fail to get them differently. Both degradations are measured and recorded rather than masked, and neither is a regression of the migration: the font seam is answered inside the browser context so that nothing leaves the machine.',
323		'Two of the four rendered-appearance probes are declared to differ across the eleven-major lift and are checked in both directions — a probe outside the declaration that differs fails the run, and a declared difference that stopped being real fails it too.',
324		'Byte parity across the lanes is not claimed and is recorded separately by the bound build receipts; eleven majors of bundler produce different file names and different byte counts by construction.',
325		'Neither build ships a service worker, and BOTH attempt to register one. The application registers at the literal `%BASE_HREF%ngsw-worker.js` — a placeholder upstream substitutes in a separate npm script that `ng build` never runs — and the request is answered 400 in both lanes. It is an era defect that survives the migration: the migration did not introduce it and no capability here repaired it, and it is recorded rather than suppressed.',
326		'Locality is process-scoped and does not establish operating-system-wide isolation.',
327		'Receipts prove reproducibility and hash integrity, not certification, authenticity, signer identity, compliance, or an earned SLSA level.',
328	]);
329	
330	async function bindCanonicalReceipts(): Promise<
331		WitnessAngularTinyTranslatorReceipt['canonicalReceipts']
332	> {
333		return await Promise.all(
334			ANGULAR_TINY_TRANSLATOR_CANONICAL_RECEIPTS.map(async (pinned) => {
335				const bytes = await readFile(join(root, pinned.path));
336				const value = JSON.parse(bytes.toString('utf8')) as {
337					schemaVersion?: unknown;
338					digest?: unknown;
339				};
340				if (
341					value.schemaVersion !== pinned.schemaVersion ||
342					value.digest !== pinned.digest ||
343					sha256(bytes) !== pinned.sha256
344				)
345					throw new Error(
346						`TinyTranslator bound build receipt identity differs: ${pinned.path}`,
347					);
348				return { ...pinned };
349			}),
350		);
351	}
352	
353	export async function runWitnessAngularTinyTranslator(): Promise<WitnessAngularTinyTranslatorReceipt> {
354		if (
355			process.env.VERSIONLESS_NETWORK_MODE !== 'offline' ||
356			process.env.NPM_CONFIG_OFFLINE !== 'true'
357		)
358			throw new Error('TinyTranslator Witness requires dual offline controls');
359		if (await exists(witnessEvidence))
360			throw new Error('TinyTranslator Witness output collision');
361		const provenance = await verifyLinkedWitnessProvenance(root);
362		const canonicalReceipts = await bindCanonicalReceipts();
363		const lanes = await stageInputs();
364		const runs = await executeRuns(lanes);
365		const mutation = await semanticMutation(lanes.migrated, runs[0]!.behaviorDigest);
366		const baseline = runs.find((entry) => entry.lane === 'baseline')!;
367		const migrated = runs.find((entry) => entry.lane === 'migrated')!;
368		const artifacts = join(fixtureEvidence, 'witness-artifacts');
369		await mkdir(artifacts, { recursive: true });
370		await writeFile(join(artifacts, 'witness-journeys.json'), `${canonicalize(runs)}\n`, {
371			flag: 'wx',
372		});
373		await writeFile(join(artifacts, 'witness-mutation.json'), `${canonicalize(mutation)}\n`, {
374			flag: 'wx',
375		});
376		const receipt: WitnessAngularTinyTranslatorReceipt = {
377			schemaVersion: WITNESS_ANGULAR_TINY_TRANSLATOR_SCHEMA,
378			result: 'pass',
379			fixture: ANGULAR_TINY_TRANSLATOR_FIXTURE,
380			source: ANGULAR_TINY_TRANSLATOR_SOURCE,
381			provenance,
382			canonicalReceipts,
383			runs,
384			mutation,
385			consoleErrors: {
386				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.baseline],
387				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_CONSOLE_ERRORS.migrated],
388			},
389			failedRequests: {
390				baseline: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.baseline],
391				migrated: [...WITNESS_ANGULAR_TINY_TRANSLATOR_FAILED_REQUESTS.migrated],
392			},
393			mockedSeams: {
394				baseline: [...baseline.mockedNonLoopbackSeams.category],
395				migrated: [...migrated.mockedNonLoopbackSeams.category],
396			},
397			fontSeamDifference: WITNESS_ANGULAR_TINY_TRANSLATOR_FONT_SEAM_DIFFERENCE,
398			serviceWorkerAttempt: WITNESS_ANGULAR_TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
399			matIconDegradations: {
400				baseline: baseline.applicationJourney.matIcon,
401				migrated: migrated.applicationJourney.matIcon,
402			},
403			renderedStyleParity: {
404				state: 'measured-resolved-styles-with-declared-differences',
405				probes: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES.length,
406				declaredDifferences: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_DIFFERENCES,
407				otherProbesAgree: true,
408			},
409			fileInput: {
410				surfaces: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES,
411				fixture: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_FIXTURE,
412				rule: WITNESS_FILE_INPUT_LOAD_RULE,
413			},
414			downloads: {
415				surface: WITNESS_ANGULAR_TINY_TRANSLATOR_DOWNLOAD_SURFACE,
416				rule: WITNESS_DOWNLOAD_CAPTURE_RULE,
417				captured: runs.map((entry) => ({
418					lane: entry.lane,
419					pass: entry.pass,
420					files: [...entry.downloadCaptures.captured],
421				})),
422			},
423			persistence: {
424				store: 'browser-local-storage',
425				backend: 'none',
426				stubbed: false,
427				survivesOnlineReload: true,
428			},
429			routeShape: WITNESS_ANGULAR_TINY_TRANSLATOR_ROUTE_SHAPE,
430			scrollAbsence: runs[0]!.scrollAbsence,
431			accommodations: WITNESS_ANGULAR_TINY_TRANSLATOR_ACCOMMODATIONS,
432			readiness: {
433				angularLineage: { ready: 1, total: 4, counted: false },
434				overall: { ready: 3, total: 12 },
435			},
436			locality: {
437				mode: 'offline',
438				successfulNonLoopback: 0,
439				osWideIsolation: false,
440				mockedNonLoopbackSeams: migrated.mockedNonLoopbackSeams.category.length,
441			},
442			nonclaims: [...WITNESS_ANGULAR_TINY_TRANSLATOR_NONCLAIMS],
443			integrity: { algorithm: 'sha256', canonicalDigest: '' },
444		};
445		receipt.integrity.canonicalDigest = witnessAngularTinyTranslatorDigest(receipt);
446		parseWitnessAngularTinyTranslatorReceipt(receipt);
447		await mkdir(witnessEvidence, { recursive: true });
448		const canonical = canonicalize(receipt);
449		/**
450		 * The companion is rendered from the receipt as PUBLISHED rather than from
451		 * the object in memory: canonicalization sorts keys, so a companion rendered
452		 * from the in-memory object would disagree with the same companion rendered
453		 * from the file, and `verify` — which only ever has the file — would be
454		 * right to reject it.
455		 */
456		const published = parseWitnessAngularTinyTranslatorReceipt(JSON.parse(canonical));
457		await writeFile(join(witnessEvidence, 'receipt.json'), `${canonical}\n`, { flag: 'wx' });
458		await writeFile(
459			join(witnessEvidence, 'receipt.md'),
460			renderWitnessAngularTinyTranslatorReceipt(published),
461			{ flag: 'wx' },
462		);
463		return published;
464	}
465	
466	export async function verifyWitnessAngularTinyTranslator(
467		output = witnessEvidence,
468	): Promise<WitnessAngularTinyTranslatorReceipt> {
469		const expectedProvenance = await verifyLinkedWitnessProvenance(root);
470		const receipt = parseWitnessAngularTinyTranslatorReceipt(
471			JSON.parse(await readFile(join(output, 'receipt.json'), 'utf8')),
472		);
473		if (canonicalize(receipt.provenance) !== canonicalize(expectedProvenance))
474			throw new Error('TinyTranslator linked Witness provenance differs');
475		for (const bound of receipt.canonicalReceipts)
476			if (sha256(await readFile(join(root, bound.path))) !== bound.sha256)
477				throw new Error(`TinyTranslator bound build receipt bytes drifted: ${bound.path}`);
478		if (
479			(await readFile(join(output, 'receipt.md'), 'utf8')) !==
480			renderWitnessAngularTinyTranslatorReceipt(receipt)
481		)
482			throw new Error('TinyTranslator human Witness receipt differs');
483		const serialized = canonicalize(receipt);
484		if (serialized.includes(root) || serialized.includes(process.env.USER ?? ''))
485			throw new Error('TinyTranslator receipt leaks host identity');
486		return receipt;
487	}
488	
489	export async function main(args = process.argv.slice(2)): Promise<void> {
490		const publishIndex = args.indexOf('--publish');
491		const verifyIndex = args.indexOf('--verify');
492		if (args.includes('--run-twice') && publishIndex >= 0 && args[publishIndex + 1]) {
493			const output = resolve(root, args[publishIndex + 1]!);
494			if (output !== witnessEvidence) throw new Error('TinyTranslator publish path differs');
495			const receipt = await runWitnessAngularTinyTranslator();
496			process.stdout.write(
497				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
498			);
499			return;
500		}
501		if (verifyIndex >= 0 && args[verifyIndex + 1]) {
502			const receipt = await verifyWitnessAngularTinyTranslator(
503				resolve(root, args[verifyIndex + 1]!),
504			);
505			process.stdout.write(
506				`${canonicalize({ result: receipt.result, digest: receipt.integrity.canonicalDigest })}\n`,
507			);
508			return;
509		}
510		throw new Error(
511			'TinyTranslator Witness runner requires --run-twice --publish <dir> or --verify <dir>',
512		);
513	}
514	
515	if (basename(process.argv[1] ?? '') === 'angular-tiny-translator-run.ts')
516		main().catch((error: unknown) => {
517			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
518			process.exitCode = 1;
519		});
