1	/**
2	 * The boot fact for one production output root of the
3	 * `angular-tiny-translator-v0-12-0` cell.
4	 *
5	 * u19d's finding was that the migrated lane's build lanes were green and
6	 * deterministic while the artifact they emitted threw before Angular
7	 * bootstrapped — a failure invisible to every check the build lanes perform,
8	 * and visible in a browser within a second of loading the page. A build record
9	 * that claims a green migrated lane without opening the artifact once is a
10	 * record that can be contradicted the same way again.
11	 *
12	 * So this is the narrowest browser measurement that would have caught it: serve
13	 * the output root over loopback, load the initial route, and read back whether
14	 * Angular's own root component rendered the home surface — with every page
15	 * error and console error the load produced recorded exactly, whether the
16	 * surface appeared or not.
17	 *
18	 * It is deliberately not a journey. No gesture is performed, no seam is mocked
19	 * and nothing is asserted about behaviour; the four uncalibrated facts the
20	 * Witness proof owes this vertical remain uncalibrated and are not touched
21	 * here. What this establishes is one fact — the bundle evaluates and the
22	 * application mounts — and that is the exact fact u19d found missing.
23	 */
24	
25	import { join, resolve } from 'pathe';
26	import { joinURL } from 'ufo';
27	import type { BrowserConsoleMessage, BrowserPageError } from '@async/witness';
28	import { createPlaywrightWitnessHost } from './playwright-host.ts';
29	import { startStaticServer } from './real-app-run.ts';
30	
31	const root = resolve(import.meta.dirname, '../../../..');
32	const chromiumExecutable = join(
33		root,
34		'.versionless/cache/react-boilerplate-v4/ms-playwright/chromium_headless_shell-1208/chrome-headless-shell-mac-arm64/chrome-headless-shell',
35	);
36	
37	/**
38	 * The route the application's own router treats as home, and the element the
39	 * home surface renders its title into. Both are read out of the served bundle
40	 * by the journey this vertical already carries; they are restated here because
41	 * a boot check that waited for nothing in particular would pass on a blank
42	 * page.
43	 */
44	export const TINY_TRANSLATOR_HOME_ROUTE = '/#/home';
45	export const TINY_TRANSLATOR_HOME_SELECTOR = '#apptitle';
46	export const TINY_TRANSLATOR_HOME_TITLE = 'Tiny Translator';
47	
48	export type BootObservation = Readonly<{
49		/** The output root served, as handed in. */
50		laneRoot: string;
51		/** The page URL, with the ephemeral loopback origin normalized away. */
52		url: string;
53		/** Whether the home surface rendered its title within the budget. */
54		booted: boolean;
55		/** The text the home selector carried, or null when it never appeared. */
56		renderedTitle: string | null;
57		/** Every uncaught page error, in observation order. */
58		pageErrors: readonly string[];
59		/** Every console error, in observation order. */
60		consoleErrors: readonly string[];
61		/** The refusal, when the surface did not render. */
62		refusal: string | null;
