export type PageHandle = {
	readonly route: string;
	readonly environment: string;
	readonly url: string;
	reload(): Promise<void>;
	content(): Promise<string>;
	/** Completed browser network requests observed through CDP. */
	networkRequests(): Promise<BrowserNetworkRequest[]>;
	/** Applies CDP network emulation before a navigation or interaction. */
	emulateNetwork(conditions: BrowserNetworkConditions): Promise<void>;
	/** Clears CDP network emulation for this page. */
	clearNetworkEmulation(): Promise<void>;
	/**
	 * Clicks the first element matching the selector, waiting (bounded,
	 * event-driven) for it to become actionable. The minimal interaction
	 * primitive for reaching a user-made UI state — for example clicking a
	 * counter to a known count before an HMR edit. Each click is recorded as
	 * page evidence; assertions stay in `expect.page.*`.
	 */
	click(selector: string, options?: { timeoutMs?: number }): Promise<void>;
	/**
	 * Focuses the first writable element matching the selector (bounded,
	 * event-driven) and types text into it — the interaction primitive for
	 * reaching form-made UI state before an edit. By default the typed text is
	 * redacted in page evidence (`textLength` stays honest); `redact: false`
	 * records it verbatim, except into password fields, which are always
	 * redacted. `keyEvents: false` inserts the text in one editing operation
	 * without key events. Assertions stay in `expect.page.*`.
	 */
	type(
		selector: string,
		text: string,
		options?: { clear?: boolean; keyEvents?: boolean; redact?: boolean; timeoutMs?: number },
	): Promise<void>;
	/**
	 * Moves the pointer over the first actionable element matching the
	 * selector, so `:hover`-revealed state becomes reachable. Each hover is
	 * recorded as page evidence; assertions stay in `expect.page.*`.
	 */
	hover(
		selector: string,
		options?: { modifiers?: KeyModifier[]; timeoutMs?: number },
	): Promise<void>;
	/**
	 * Focuses the element and presses one key, optionally chorded with
	 * modifiers (for example `press('#form', 'Enter', { modifiers: ['Meta'] })`).
	 * Each press is recorded as page evidence; assertions stay in
	 * `expect.page.*`.
	 */
	press(
		selector: string,
		key: string,
		options?: { modifiers?: KeyModifier[]; timeoutMs?: number },
	): Promise<void>;
	/**
	 * Pointer drag from a source element to a target element or fixed
	 * viewport coordinates, with interpolated intermediate moves (drag
	 * libraries only track after movement past a threshold; `steps` defaults
	 * to 4). Native HTML5 drag-and-drop (`draggable="true"`) is not driven by
	 * synthetic pointer events and is not covered. Each drag is recorded as
	 * page evidence; assertions stay in `expect.page.*`.
	 */
	drag(
		from: string,
		to: string | { x: number; y: number },
		options?: { steps?: number; timeoutMs?: number },
	): Promise<void>;
	/**
	 * Scrolls by wheel deltas (DOM sign: positive y scrolls down) at the
	 * first element matching the selector, or the viewport for `null`. The
	 * driver confirms — event-driven — that something actually scrolled.
	 * `gesture: true` uses a real compositor gesture with momentum instead of
	 * one wheel frame. Each scroll is recorded as page evidence; assertions
	 * stay in `expect.page.*`.
	 */
	scroll(
		target: string | null,
		delta: { x?: number; y?: number },
		options?: { gesture?: boolean; timeoutMs?: number },
	): Promise<void>;
	/**
	 * Starts counting custom DOM events (for example a framework's HMR event)
	 * in the live page. Observed events land in the page receipt evidence and
	 * are asserted with `expect.page.event(page, name, { atLeast })`.
	 * Tracking is per-document: a full reload discards in-page listeners,
	 * which `navigations` evidence makes visible.
	 */
	trackEvents(...eventNames: string[]): Promise<void>;
};

export type BrowserVisitOptions = {
	/** Applies CDP network emulation before the initial navigation. */
	readonly networkConditions?: BrowserNetworkConditions;
};

export type VisitArgs = {
	baseUrl: string;
	route: string;
	environment: string;
	surface: 'dev' | 'preview';

