		condition,
		timeoutMs: waitOptions?.timeoutMs ?? defaultTimeoutMs,
		describeFailure: async () => {
			const actual = await readPageState(
				page,
				`(() => { const el = ${element}; return el === null ? { missing: true } : { value: el.getAttribute(${JSON.stringify(attributeName)}) }; })()`,
