1	/**
2	 * TinyTranslator Witness calibration — the RED record.
3	 *
4	 * The u19d unit set out to calibrate four uncalibrated journey facts and then
5	 * publish the browser proof. The calibration pass answered a prior question
6	 * instead: neither lane behaves the way the Witness schema assumes, and the
7	 * migrated lane does not run in a browser at all. A break across the
8	 * eleven-major lift is evidence, and evidence is recorded before anything else
9	 * is attempted — so this driver measures the break rather than describing it,
10	 * and publishes what it measured.
11	 *
12	 * Everything below is measured in this process: the two browser passes are run
13	 * here, their page errors, console messages and requests are read back out of
14	 * the runner's own receipts, and the byte-level facts are read out of the two
15	 * pinned output roots. The only pinned inputs are the roots themselves and the
16	 * bound build record whose inventory digest is re-derived to prove that the
17	 * tree measured IS the tree that record published.
18	 */
19	import { cp, mkdir, readFile, readdir, rm, writeFile } from 'node:fs/promises';
20	import { join, relative, resolve } from 'pathe';
21	import { sha256 } from '../../../core/src/receipts/canonicalize.ts';
22	import { canonical } from './angular-factoriolab-migration-run.ts';
23	import {
24		sealRecord,
25		verifySealedRecord,
26		type SealedRecord,
27	} from './angular-factoriolab-build-lanes-run.ts';
28	import { executeAngularTinyTranslatorWitnessRun } from '../witness/real-app-run.ts';
29	
30	const root = resolve(import.meta.dirname, '../../../..');
31	export const EVIDENCE_DIRECTORY = join(root, 'evidence/runs/angular-tiny-translator-v0-12-0');
32	export const WITNESS_RED_FILE = 'u19d-witness-calibration-red.json';
33	const BOUND_MIGRATED_RECORD = 'u17d-final-green-lane.json';
34	const stage = join(root, '.versionless/stage/witness-angular-tiny-translator-calibrate');
35	const laneRoots = {
36		baseline: join(
37			root,
38			'.versionless/cache/angular-tiny-translator-v0-12-0-baseline/app/dist/rebuild-1',
39		),
40		migrated: join(root, '.versionless/stage/angular-tiny-translator-v0-12-0-u17b/dist-7'),
41	} as const;
42	/** The placeholder the ephemeral loopback origin is normalized to. */
43	const ORIGIN_PLACEHOLDER = '{production-static-origin}';
44	/**
45	 * The era build's registration argument, unsubstituted. The upstream project
46	 * replaces `%BASE_HREF%` in a separate `replace` npm script that `ng build
47	 * --prod` alone never runs, so the AOT factory carries the placeholder itself.
48	 */
49	const ERA_SERVICE_WORKER_SCRIPT = '%BASE_HREF%ngsw-worker.js';
50	/**
51	 * The statement that kills the migrated bundle. `util@0.12.5` — the browser
52	 * implementation of the Node core module, declared for `ngx-i18nsupport-lib` by
53	 * the u17c capability and recorded as a standing risk by the bound u17d record
54	 * — reads `process.env.NODE_DEBUG` at module evaluation time.
55	 */
56	const MIGRATED_PROCESS_STATEMENT = 'if(process.env';
57	
58	type LaneName = 'baseline' | 'migrated';
59	
60	type PageObservation = {
61		/** The ephemeral loopback origin this pass ran on, normalized out of everything. */
62		origin: string;
63		booted: boolean;
64		pageErrors: string[];
65		consoleErrors: string[];
66		requests: Array<{ status: number | null; url: string; failedReason: string | null }>;
67	};
68	
69	async function files(directory: string): Promise<string[]> {
70		const output: string[] = [];
71		for (const entry of await readdir(directory, { withFileTypes: true })) {
72			const path = join(directory, entry.name);
73			if (entry.isDirectory()) output.push(...(await files(path)));
74			else if (entry.isFile()) output.push(path);
75		}
76		return output.sort();
77	}
78	
79	/** The inventory the bound record addresses, recomputed rather than restated. */
80	async function inventoryDigestOf(rootDirectory: string): Promise<{
81		files: number;
82		digest: string;
83	}> {
84		const inventory: Array<{ path: string; sha256: string; bytes: number }> = [];
85		for (const file of await files(rootDirectory)) {
86			const bytes = await readFile(file);
87			inventory.push({
88				path: relative(rootDirectory, file),
89				sha256: sha256(bytes),
90				bytes: bytes.length,
91			});
92		}
93		return {
94			files: inventory.length,
95			digest: sha256(`${JSON.stringify(inventory, null, 2)}\n`),
96		};
97	}
98	
99	/** Every served module carrying a needle, with the offset it carries it at. */
100	async function needleSites(
101		rootDirectory: string,
102		needle: string,
103	): Promise<Array<{ path: string; sha256: string; bytes: number; offset: number; count: number }>> {
104		const sites: Array<{
105			path: string;
106			sha256: string;
107			bytes: number;
108			offset: number;
109			count: number;
110		}> = [];
111		const target = Buffer.from(needle);
112		for (const file of await files(rootDirectory)) {
113			const bytes = await readFile(file);
114			const offset = bytes.indexOf(target);
115			if (offset < 0) continue;
116			let count = 0;
117			for (let at = offset; at >= 0; at = bytes.indexOf(target, at + 1)) count += 1;
118			sites.push({
119				path: relative(rootDirectory, file),
120				sha256: sha256(bytes),
121				bytes: bytes.length,
122				offset,
123				count,
124			});
125		}
126		return sites;
127	}
128	
129	/** The runner's own receipt for a single attempted pass. */
130	async function readPassReceipt(receiptRoot: string, lane: LaneName): Promise<PageObservation> {
131		const passDirectory = join(receiptRoot, 'angular-tiny-translator', lane, 'pass-1');
132		const runs = (await readdir(passDirectory, { withFileTypes: true }))
133			.filter((entry) => entry.isDirectory())
134			.map((entry) => entry.name)
135			.sort();
136		const runId = runs[runs.length - 1];
137		if (runId === undefined) throw new Error(`TinyTranslator ${lane} pass wrote no receipt`);
138		const receipt = JSON.parse(
139			await readFile(join(passDirectory, runId, 'receipt.json'), 'utf8'),
140		) as {
141			boxes?: Array<{
142				pages?: Array<{
143					url?: string;
144					pageErrors?: Array<{ message?: string }>;
145					consoleMessages?: Array<{ level?: string; text?: string }>;
146					networkRequests?: Array<{ status?: number; url?: string; failedReason?: string }>;
147				}>;
148			}>;
149		};
150		const page = receipt.boxes?.[0]?.pages?.[0];
151		const requests = page?.networkRequests ?? [];
152		const [scheme, , authority] = (page?.url ?? '').split('/');
153		const origin = `${scheme ?? ''}//${authority ?? ''}`;
154		const normalize = (value: string): string => value.split(origin).join(ORIGIN_PLACEHOLDER);
155		return {
156			origin,
157			booted: (page?.pageErrors ?? []).length === 0,
158			pageErrors: (page?.pageErrors ?? []).map((entry) => normalize(entry.message ?? '')),
159			consoleErrors: (page?.consoleMessages ?? [])
160				.filter((entry) => entry.level === 'error')
161				.map((entry) => normalize(entry.text ?? '')),
162			requests: requests.map((entry) => ({
163				status: entry.status ?? null,
164				url: normalize(entry.url ?? ''),
165				failedReason: entry.failedReason ?? null,
166			})),
167		};
168	}
169	
170	/** One calibration pass per lane, against a staged copy of the pinned root. */
171	async function measureLane(
172		lane: LaneName,
173	): Promise<{ refusal: string; observation: Omit<PageObservation, 'origin'> }> {
174		const laneRoot = join(stage, 'lanes', lane);
175		const receiptRoot = join(stage, 'receipts', lane);
176		await rm(laneRoot, { recursive: true, force: true });
177		await rm(receiptRoot, { recursive: true, force: true });
178		await mkdir(laneRoot, { recursive: true });
179		await cp(laneRoots[lane], laneRoot, { recursive: true });
180		let refusal = '';
181		try {
182			await executeAngularTinyTranslatorWitnessRun({ lane, pass: 1, laneRoot, receiptRoot });
183		} catch (error) {
184			refusal = (error instanceof Error ? error.message : String(error)).split('\n')[0] ?? '';
185		}
186		const { origin, ...observation } = await readPassReceipt(receiptRoot, lane);
187		return {
188			refusal: refusal.split(root).join('{repository-root}').split(origin).join(ORIGIN_PLACEHOLDER),
189			observation,
190		};
191	}
192	
193	export async function buildWitnessRedRecord(): Promise<SealedRecord> {
194		const baseline = await measureLane('baseline');
195		const migrated = await measureLane('migrated');
196		const boundBytes = await readFile(join(EVIDENCE_DIRECTORY, BOUND_MIGRATED_RECORD));
197		const bound = JSON.parse(boundBytes.toString('utf8')) as {
198			digest?: string;
199			determinism?: { inventorySha256?: string };
200		};
201		const migratedInventory = await inventoryDigestOf(laneRoots.migrated);
202		const baselineInventory = await inventoryDigestOf(laneRoots.baseline);
203		const processSites = await needleSites(laneRoots.migrated, MIGRATED_PROCESS_STATEMENT);
204		const registrationSites = await needleSites(laneRoots.baseline, ERA_SERVICE_WORKER_SCRIPT);
205		const shippedWorkers = (await files(laneRoots.baseline))
206			.map((file) => relative(laneRoots.baseline, file))
207			.filter((path) => path.includes('ngsw'));
208		return sealRecord({
209			schemaVersion: 'versionless.angular-tiny-translator-witness-red.v1',
210			unit: 'u19d-tiny-translator-calibrate-publish',
211			result: 'witness-calibration-red-migrated-lane-does-not-boot',
212			meaning:
213				'The calibration pass this unit opened with answered a question that comes before its four uncalibrated facts. The migrated production build — the exact tree the bound u17d record published — throws before Angular bootstraps and renders nothing at all, and the era build attempts a service-worker registration the Witness schema says neither build attempts. Neither lane can be published as a passing browser proof, so nothing was published. This record is the refusal, with the measurements it rests on.',
214			measuredBy:
215				'one Witness pass per lane, executed by the same runner the proof would have used, against staged copies of the two pinned output roots; page errors, console errors and requests read back out of the runner own per-pass receipts, with the ephemeral loopback origin normalized to a placeholder',
216			pinnedRoots: {
217				baseline: {
218					root: 'evidence-bound era lane canonical root dist/rebuild-1',
219					files: baselineInventory.files,
220					inventorySha256: baselineInventory.digest,
221				},
222				migrated: {
223					root: 'evidence-bound migrated lane canonical root dist-7',
224					files: migratedInventory.files,
225					inventorySha256: migratedInventory.digest,
226					boundRecord: BOUND_MIGRATED_RECORD,
227					boundRecordDigest: bound.digest ?? null,
228					boundRecordSha256: sha256(boundBytes),
229					boundInventorySha256: bound.determinism?.inventorySha256 ?? null,
230					// The point of recomputing it: the tree that failed to boot is the
231					// tree that record published, not a stale or re-run build.
232					isTheBoundArtifact: migratedInventory.digest === bound.determinism?.inventorySha256,
233				},
234			},
235			findings: [
236				{
237					id: 'migrated-lane-does-not-boot',
238					lane: 'migrated',
239					severity: 'red',
240					kind: 'runtime-only migration regression, invisible to both build lanes',
241					observed: {
242						booted: migrated.observation.booted,
243						pageErrors: migrated.observation.pageErrors,
244						consoleErrors: migrated.observation.consoleErrors,
245						requests: migrated.observation.requests,
246						refusal: migrated.refusal,
247					},
248					byteEvidence: {
249						needle: MIGRATED_PROCESS_STATEMENT,
250						sites: processSites,
251					},
252					cause: 'ngx-i18nsupport-lib — the library that parses the translation files this application exists to edit — requires the Node core module `util`. The era webpack 3 build supplied both that module and a `process` shim automatically. The migrated lane declares `util@0.12.5` (the u17c node-core-module capability) but nothing supplies `process`, and `util` reads `process.env.NODE_DEBUG` at module evaluation time, so the main bundle throws before Angular bootstraps.',
253					consequence:
254						'The migrated lane renders nothing. No journey can pass on it truthfully, so the FileReader parity arbitration this vertical was built to perform cannot be attempted: the parse path is behind a bundle that never evaluates.',
255					alreadyRecordedAsRisk:
256						'The bound u17d record carries this exact dependency as a recorded risk — "`util@0.12.5`, the browser implementation of the Node core module, remains in the declared closure for ngx-i18nsupport-lib". This unit measures what that risk does in a browser.',
257					notFixedHere:
258						'The fix belongs to the migration capability that declares the shim, which is outside this unit file contract, and it invalidates the bound build record. Nothing was patched, masked or worked around here.',
259				},
260				{
261					id: 'era-lane-registers-a-service-worker',
262					lane: 'baseline',
263					severity: 'red',
264					kind: 'schema premise contradicted by measurement',
265					observed: {
266						booted: baseline.observation.booted,
267						pageErrors: baseline.observation.pageErrors,
268						consoleErrors: baseline.observation.consoleErrors,
269						requests: baseline.observation.requests,
270						refusal: baseline.refusal,
271					},
272					byteEvidence: {
273						needle: ERA_SERVICE_WORKER_SCRIPT,
274						sites: registrationSites,
275						shippedServiceWorkerFiles: shippedWorkers,
276					},
277					cause: 'The era production build was emitted with the service worker enabled, and its AOT factory carries the registration argument `%BASE_HREF%ngsw-worker.js` with the placeholder unsubstituted: upstream substitutes it in a separate `replace` npm script that `ng build --prod` alone never runs. The build also ships no worker script at any path, so the registration could not have succeeded even with the placeholder resolved.',
278					consequence:
279						'Three published premises are contradicted at once: the zero-service-worker policy the runner executes this application under, the empty baseline console-error inventory, and the nonclaim that neither build registers a service worker and that the zero is the application own behavior. The application does attempt one, and it fails.',
280					notFixedHere:
281						'This finding is calibratable — the attempt, its failure and its two console errors could all be pinned exactly — but calibrating it would publish a lane pair whose other half does not boot. It is recorded and left uncalibrated.',
282				},
283			],
284			uncalibratedFacts: [
285				{
286					fact: 'TINY_TRANSLATOR_JOURNEY_NAVIGATIONS',
287					state: 'unmeasurable',
288					why: 'the journey never reaches its clean-page assertion in either lane',
289				},
290				{
291					fact: 'per-lane console-error inventories',
292					state: 'partially-measured',
293					why: 'the era lane measured two errors, both consequences of the failed service-worker registration; the migrated lane measured a page error and no console error, because nothing after the throw ran',
294				},
295				{
296					fact: 'scroll absence',
297					state: 'unmeasurable',
298					why: 'no stage of the journey is reached in either lane',
299				},
300				{
301					fact: 'Material 5-vs-16 selector viability',
302					state: 'unmeasurable',
303					why: 'the migrated lane renders no DOM to select against, and the era lane refuses before its first selector',
304				},
305			],
306			notEstablished: [
307				'Nothing here establishes that the migrated build is wrong in any other respect. Its build lanes are green and deterministic and that record stands unchanged; what is established is that the artifact those lanes emitted does not run in a browser.',
308				'No claim is made about how many other failures lie behind the boot failure. One throw was measured, and a bundle that throws at evaluation hides everything after it.',
309				'The era lane was refused at its first checkpoint, so nothing is established about the rest of its journey either.',
310				'No Witness receipt was published for this vertical, and the readiness tallies are unchanged and uncounted.',
311			],
312		});
313	}
314	
315	export async function main(): Promise<void> {
316		const record = verifySealedRecord(await buildWitnessRedRecord());
317		await mkdir(EVIDENCE_DIRECTORY, { recursive: true });
318		await writeFile(join(EVIDENCE_DIRECTORY, WITNESS_RED_FILE), canonical(record));
319		process.stdout.write(
320			`witness calibration ${String(record['result'])}, digest ${String(record['digest']).slice(0, 12)}\n`,
321		);
322	}
323	
324	if (process.argv[1]?.endsWith('angular-tiny-translator-witness-red-record.ts'))
325		main().catch((error: unknown) => {
326			process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`);
327			process.exitCode = 1;
328		});
